-- The connection_folder and saved_connection tables of a real Beekeeper Studio 6.2.2 app.db
-- (see README.md): definitions as Beekeeper created them, rows as it wrote them, only the
-- user's folder in paths replaced.
CREATE TABLE connection_folder (
        id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
        name VARCHAR(255) NOT NULL,
        description VARCHAR(255),
        expanded BOOLEAN NOT NULL DEFAULT 1,
        parentId INTEGER REFERENCES connection_folder(id) ON DELETE SET NULL,
        createdAt DATETIME NOT NULL DEFAULT (datetime('now')),
        updatedAt DATETIME NOT NULL DEFAULT (datetime('now')),
        version INTEGER NOT NULL DEFAULT 0
      );
CREATE TABLE "saved_connection" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "createdAt" datetime NOT NULL DEFAULT (datetime('now')), "updatedAt" datetime NOT NULL DEFAULT (datetime('now')), "version" integer NOT NULL, "connectionType" varchar NOT NULL, "host" varchar, "port" integer, "username" varchar, "defaultDatabase" varchar, "path" varchar, "url" varchar, "uniqueHash" varchar(500) NOT NULL, "name" varchar NOT NULL, "password" varchar, "sshEnabled" boolean NOT NULL DEFAULT (0), "sshHost" varchar, "sshPort" integer, "sshMode" varchar(8) NOT NULL DEFAULT ('keyfile'), "sshKeyfile" varchar, "sshUsername" varchar, "rememberPassword" boolean NOT NULL DEFAULT (1), "rememberSshPassword" boolean NOT NULL DEFAULT (1), "rememberSshKeyfilePassword" boolean NOT NULL DEFAULT (1), "sshKeyfilePassword" varchar, "sshPassword" varchar, ssl boolean not null default false, sshBastionHost varchar(255) default null, labelColor varchar(255) default 'default', serviceName varchar(255) null default null, domain varchar(255) default null, sslCaFile varchar, sslCertFile varchar, sslKeyFile varchar, sslRejectUnauthorized boolean not null default true, workspaceId integer not null default -1, trustServerCertificate boolean not null default false, socketPathEnabled boolean not null default false, socketPath varchar(255) null, options text not null default '{}', sshKeepaliveInterval int(11) null DEFAULT 60, redshiftOptions text not null default '{}', cassandraOptions text not null default '{}', readOnlyMode boolean not null default false, bigQueryOptions text not null default '{}', azureAuthOptions TEXT NOT NULL DEFAULT '{}', authId INTEGER NULL, libsqlOptions text not null default '{}', sqlAnywhereOptions text not null default '{}', surrealDbOptions text not null default '{}', iamAuthOptions TEXT NOT NULL DEFAULT '{}', connectionFolderId INTEGER REFERENCES connection_folder(id) ON DELETE SET NULL, position FLOAT NOT NULL DEFAULT 0, sshBastionHostPort int(11) null DEFAULT null, sshBastionMode varchar(8) not null DEFAULT 'agent', sshBastionUsername varchar(255) null DEFAULT null, sshBastionKeyfile varchar(255) null DEFAULT null, sshBastionPassword varchar(255) null DEFAULT null, sshBastionKeyfilePassword varchar(255) null DEFAULT null, dynamoDbOptions TEXT NOT NULL DEFAULT '{}', snowflakeOptions text not null default '{}', windowsAuthEnabled boolean not null default false, sqlServerOptions text not null default '{}');
